slides = [('problem', '01 · المشكلة', 'المشكلة', '<div class="concept-split"><div><p class="lead">مع كل إصدار، يتكرر العمل اليدوي نفسه: إعداد الاختبارات، تنفيذ الفحوص، وتجميع الأدلة.</p><div class="task-list"><span>إعادة كتابة الحالات</span><span>إعادة الفحص</span><span>إعداد التقرير</span></div><p class="proof">الحاجة: أتمتة العمل المتكرر لتوفير وقت المختبِر للتحليل ومراجعة العيوب.</p></div><div class="time-visual" aria-label="حلقة العمل اليدوي تستهلك وقت المختبر"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="25"/><path d="M32 16v17l12 8M9 11l-5 9 11-1M55 53l5-9-11 1"/></svg><strong>وقت المختبِر</strong><span class="orbit a" data-reveal="1"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M14 5h25l13 13v41H14ZM39 5v15h13M23 31h20M23 40h20M23 49h13"/></svg>إعداد</span><span class="orbit b" data-reveal="2"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><rect x="7" y="8" width="50" height="48" rx="8"/><path d="m19 32 9 9 18-20"/></svg>فحص</span><span class="orbit c" data-reveal="3"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M14 5h25l13 13v41H14ZM39 5v15h13M23 31h20M23 40h20M23 49h13"/></svg>تقرير</span><p>نفس الجهد مع كل إصدار</p></div></div>', 'اربط المشكلة بوقت المختبر والحاجة للأتمتة. حالة المغادرة قبل الوصول مثال لقاعدة يجب إعادة فحصها قبل الإصدار. لا توجد دراسة زمنية قبل/بعد، فلا تذكر وفرًا مقاسًا.', 3), ('solution', '02 · الحل', 'الحل', '<p class="lead">أداة لتنظيم وأتمتة اختبارات البرمجيات، تربط المتطلب بالاختبار والنتيجة والدليل.</p><div class="solution-map"><div class="input-stack" data-reveal="1"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M14 5h25l13 13v41H14ZM39 5v15h13M23 31h20M23 40h20M23 49h13"/></svg><h3>متطلبات النظام</h3><p>وصف · صور · ملفات</p></div><span class="connector">←</span><div class="test-hub" data-reveal="2"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><rect x="7" y="8" width="50" height="48" rx="8"/><path d="m19 32 9 9 18-20"/></svg><h2>أداة اختبار البرمجيات</h2><p>إعداد الحالات · اعتمادها · تشغيلها</p></div><span class="connector">←</span><div class="output-stack" data-reveal="3"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M8 6v51h50M20 46V29h8v17M36 46V12h8v34M13 20l13-9 12 1 17-8"/></svg><h3>نتيجة موثقة</h3><p>المتوقع · الفعلي · الدليل</p></div></div><p class="proof">المتطلب والحالة والنتيجة في مسار واحد، بدل جمعها يدويًا من أماكن متفرقة.</p>', 'سرج اسم المشروع، لكن التعريف هنا وظيفي لا علامة تسويقية. الأداة تعمل دون نموذج ذكاء في المسار اليدوي، وتنفيذ API منفصل عن اقتراح المسودات.', 3), ('scope', '03 · نطاق الحل', 'نطاق الحل', '<div class="scope-visual-list"><article data-reveal="1"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M14 5h25l13 13v41H14ZM39 5v15h13M23 31h20M23 40h20M23 49h13"/></svg><div><h3>مصادر مرنة</h3><p>نصوص، صور وملفات مهيكلة؛ ومحتوى Word بالنسخ كنص.</p></div></article><article data-reveal="2"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><rect x="7" y="8" width="50" height="48" rx="8"/><path d="m19 32 9 9 18-20"/></svg><div><h3>إعداد حالات الاختبار</h3><p>خطوات ونتائج متوقعة قابلة للمراجعة والاعتماد.</p></div></article><article data-reveal="3"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="m22 15-17 17 17 17M42 15l17 17-17 17M37 7 27 57"/></svg><div><h3>تنفيذ وتوثيق</h3><p>فحوص API آلية، وتسجيل مستقل لتجربة المختبِر اليدوية.</p></div></article><article data-reveal="3"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M8 6v51h50M20 46V29h8v17M36 46V12h8v34M13 20l13-9 12 1 17-8"/></svg><div><h3>نتائج وأدلة وتقارير</h3><p>مقارنة المتوقع بالفعلي وتصدير التقرير للمراجعة.</p></div></article></div><p class="small">النطاق الحالي لا يشمل أتمتة المتصفح أو اختبارات الحمل. رفع ملف Word مباشرة ليس مدعومًا حاليًا.</p>', 'تسجيل المشاهدة اليدوية لا يعني تحكمًا آليًا في المتصفح. تحليل صورة لا يثبت تفاعل النظام الحي. الوثائق لا تجعل النطاق أوسع من التنفيذ الحقيقي.', 3), ('tools', '04 · الأدوات والتقنيات', 'الأدوات والتقنيات', '<div class="tools-layout"><table class="evidence-table"><thead><tr><th>الأساس</th><th>الأداة</th><th>الاستخدام</th></tr></thead><tbody><tr><td>منهجية الاختبار</td><td dir="auto">ISTQB CTFL</td><td>التتبع بين المتطلبات والحالات والنتائج.</td></tr><tr data-reveal="1"><td>التطوير بمساعدة وكيل</td><td dir="auto">OpenClaw Agent</td><td>تخطيط وتوليد وتنقيح الكود، مع مراجعة المخرجات واختبارها.</td></tr><tr data-reveal="2"><td>محركات الفحص</td><td dir="auto">C# · Dart</td><td>تنفيذ تعريف مشترك وشروط نجاح صريحة.</td></tr><tr><td>التطبيق</td><td dir="auto">React · TypeScript<br>ASP.NET Core · SQLite</td><td>واجهة العمل والخدمات وحفظ البيانات.</td></tr><tr data-reveal="3"><td>مساعد داخل المنتج</td><td dir="auto">Cloudflare Workers AI<br>Llama 3.3 · Llama 4 Scout</td><td>اقتراح مسودات من النص والصور.</td></tr></tbody></table><div class="agent-visual"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><rect x="10" y="18" width="44" height="34" rx="10"/><path d="M32 8v10M5 30h5m44 0h5M23 31v5m18-5v5M23 44h18"/><circle cx="32" cy="7" r="3"/></svg><strong>OpenClaw</strong><span>توجيه</span><div class="agent-loop">توليد الكود<br>↓<br>مراجعة واختبار<br>↺</div><p>دور الوكيل في البناء<br>منفصل عن ذكاء المنتج</p></div></div><p class="references"><a href="https://www.istqb.org/wp-content/uploads/2024/11/ISTQB_CTFL_Syllabus_v4.0.1.pdf" target="_blank" rel="noopener">ISTQB CTFL v4.0.1</a> · <a href="https://developers.cloudflare.com/workers-ai/platform/pricing/" target="_blank" rel="noopener">Cloudflare</a> · المرجع منهجي، وليس اعتمادًا للمنتج. الذكاء يقترح ولا يحكم نتيجة الفحص.</p>', 'التطوير بمساعدة OpenClaw Agent وفق توضيح خالد. مساعد المنتج Cloudflare ونموذجا Meta Llama منفصلان عن وكيل البناء. ISTQB مرجع تنظيمي، لا شهادة اعتماد للمنتج.', 3), ('experience-start', '05 · تجربة المنتج', 'تجربة المنتج', '<div class="journey-heading"><span class="pill">1 / 4 · المصادر</span><p>أضف وصف النظام ومصادره، ثم ارجع إليها أثناء إعداد الاختبارات.</p></div><figure class="picture journey-image"><a href="assets/current-sources.png" target="_blank" rel="noopener" aria-label="فتح لقطة المنتج بالحجم الكامل"><img src="assets/current-sources.png" alt="واجهة المطلوب الحالية: وصف نصي ومواصفات مهيكلة لنفس مشروع الحجوزات."/></a></figure><p class="picture-label">واجهة المطلوب الحالية: وصف نصي ومواصفات مهيكلة لنفس مشروع الحجوزات. اضغط الصورة لتكبيرها.</p>', 'لقطة جديدة التقطت 11 نوفمبر 2026 من التطبيق الحالي، ببيانات اصطناعية في مساحة تصوير منفصلة. واجهة المطلوب الحالية: وصف نصي ومواصفات مهيكلة لنفس مشروع الحجوزات.', 0), ('experience-case', '05 · تجربة المنتج', 'تجربة المنتج', '<div class="journey-heading"><span class="pill">2 / 4 · حالات الاختبار</span><p>حالتان واضحتان: حجز صحيح، وحجز بتواريخ غير منطقية.</p></div><div class="paired-captures"><figure class="picture"><a href="assets/current-check-valid.png" target="_blank" rel="noopener" aria-label="تكبير لقطة المنتج"><img src="assets/current-check-valid.png" alt="الحالة الصحيحة"/></a><figcaption>الحالة الصحيحة</figcaption></figure><figure class="picture"><a href="assets/current-check-invalid.png" target="_blank" rel="noopener" aria-label="تكبير لقطة المنتج"><img src="assets/current-check-invalid.png" alt="التواريخ المعكوسة"/></a><figcaption>التواريخ المعكوسة</figcaption></figure></div><p class="picture-label">لقطات حديثة من نفس مشروع التجربة المحلية، وليست نتائج نظام إنتاج. اضغط الصورة لتكبيرها.</p>', 'لقطة جديدة التقطت 11 نوفمبر 2026 من التطبيق الحالي، ببيانات اصطناعية في مساحة تصوير منفصلة. واجهة اختباراتي الحالية: حالات حجز صحيحة ومعكوسة التواريخ.', 0), ('experience-execute', '05 · تجربة المنتج', 'تجربة المنتج', '<div class="journey-heading"><span class="pill">3 / 4 · تنفيذ الفحص</span><p>شغّل فحوص الخدمة المعتمدة وراجع سبب الحكم.</p></div><div class="execution-evidence"><div class="verdict-visual"><p>حجز بتاريخ مغادرة يسبق الوصول</p><div class="http-comparison"><div><span>المتوقع: رفض الطلب</span><b dir="ltr">400</b></div><div><span>الفعلي: قُبل الحجز</span><b dir="ltr">201</b></div></div><strong>النتيجة: كشف مخالفة القاعدة</strong><p>نجاح طلب HTTP ليس بالضرورة نجاحًا لاختبار قاعدة العمل.</p></div><figure class="picture"><a href="assets/current-execute.png" target="_blank" rel="noopener"><img src="assets/current-execute.png" alt="آخر تشغيل حقيقي: حالة ناجحة وأخرى فاشلة وحالة تحتاج مراجعة"/></a></figure></div><p class="picture-label">تشغيل C# حديث على محاكي محلي متعمّد الخلل، وليس على نظام إنتاج.</p>', 'لقطة جديدة التقطت 11 نوفمبر 2026 من التطبيق الحالي، ببيانات اصطناعية في مساحة تصوير منفصلة. تشغيل C# فعلي على محاكي محلي متعمّد الخلل، وليس على نظام إنتاج.', 0), ('experience-result', '05 · تجربة المنتج', 'تجربة المنتج', '<div class="journey-heading"><span class="pill">4 / 4 · النتائج والتقرير</span><p>المتوقع والفعلي والخطوة التالية، في نتيجة مفهومة قابلة للمشاركة.</p></div><figure class="picture journey-image"><a href="assets/current-result-invalid.png" target="_blank" rel="noopener"><img src="assets/current-result-invalid.png" alt="نتيجة الفحص الآلي لرفض المغادرة قبل الوصول مع المتوقع والفعلي"/></a></figure><p class="picture-label">نتيجة حديثة من نفس مشروع التجربة المحلية. التقرير يضم الحالات والأدلة؛ اضغط الصورة لتكبيرها.</p>', 'لقطة جديدة التقطت 11 نوفمبر 2026 من التطبيق الحالي، ببيانات اصطناعية في مساحة تصوير منفصلة. نتائج آلية لنفس مشروع التجربة المحلية؛ الحجز الصحيح سليم والمعكوس كشف مشكلة.', 0), ('integration', '06 · التكامل مع الأنظمة', 'التكامل مع الأنظمة', '<p class="lead">تدخل الأداة في سير العمل عبر مصادر النظام وواجهاته، دون استبدال النظام القائم.</p><div class="integration-map"><div data-reveal="1"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M14 5h25l13 13v41H14ZM39 5v15h13M23 31h20M23 40h20M23 49h13"/></svg><h3>مصادر النظام</h3><p>وصف ومستندات وصور<br>JSON / YAML<br>محتوى Word كنص</p></div><span class="connector">←</span><div class="integration-core" data-reveal="2"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><rect x="7" y="8" width="50" height="48" rx="8"/><path d="m19 32 9 9 18-20"/></svg><h3>أداة الاختبار</h3><p>حالات معتمدة<br>اتصال API بصلاحيات محددة</p></div><span class="connector">←</span><div data-reveal="3"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M8 6v51h50M20 46V29h8v17M36 46V12h8v34M13 20l13-9 12 1 17-8"/></svg><h3>مخرجات الفريق</h3><p>نتائج وأدلة<br>تقارير HTML / RTF<br>JSON للمعالجة</p></div></div><p class="proof">مصدر قابل للتعديل وتعريف موحّد للاختبار يسهّلان بناء روابط تناسب نظام العمل.</p><p class="small">المتاح الآن: مصادر وواجهات وتقارير. التحويل إلى موديول ERP متكامل ضمن فرص التطوير.</p>', 'API الخلفية لا يُوصف بأنه واجهة تكامل مؤسسي مستقرة للعامة. استيراد OpenAPI ليس مزامنة ثنائية الاتجاه. مرونة المصدر تسمح بالتوسعة لكنها تحتاج تطويرًا وصيانة. النظام لا يستبدل CI أو نظام التذاكر الحالي.', 3), ('costs', '07 · التكاليف', 'التكاليف', '<div class="cost-visual" aria-label="قيمة الأتمتة: تخفيض العمل المتكرر مع احتساب المراجعة"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="25"/><path d="M32 16v17l12 8M9 11l-5 9 11-1M55 53l5-9-11 1"/></svg><div><strong>عمل يدوي متكرر</strong><span class="time-bar manual"></span></div><span class="connector">←</span><div><strong>أتمتة + مراجعة</strong><span class="time-bar automated"></span></div><span class="cost-visual-note">تصور للفكرة، وليس قياسًا</span></div><p class="cost-basis">مقارنة رسوم الاستخدام · USD · خمسة مستخدمين · دفع سنوي · دون الضرائب</p><table class="evidence-table costs-table"><thead><tr><th>الخيار</th><th>الاشتراك</th><th>الحدود والتخصيص</th></tr></thead><tbody><tr data-reveal="1"><td>الأداة الحالية محليًا</td><td>دون رسم اشتراك مستخدمين</td><td>مصدر قابل للتعديل؛ الجهاز والصيانة والاستضافة خارج الرقم. الذكاء بحصة محدودة.</td></tr><tr data-reveal="2"><td dir="ltr">TestRail Essentials</td><td><b dir="ltr">$22</b> للمستخدم/شهر<br><b dir="ltr">$1,320</b> سنويًا لخمسة</td><td>حتى 5 مستخدمين؛ القوالب المخصصة وUI scripts في Professional بسعر $38.</td></tr><tr data-reveal="3"><td dir="ltr">Qase Teams</td><td><b dir="ltr">$35</b> للمستخدم/شهر<br><b dir="ltr">$2,100</b> سنويًا لخمسة</td><td>حد أدنى 5؛ حقول مخصصة وتكاملات. توجد خطة مجانية حتى 4 مستخدمين بقيود.</td></tr></tbody></table><p class="cost-model">الوقت الموفر = زمن المهمة يدويًا − زمنها بالأداة شامل المراجعة.<br><span class="muted">لم يُقَس بعد. سيناريو توضيحي: إذا انخفضت 30 إلى 15 دقيقة × 20 مرة = 5 ساعات مستعادة.</span></p><p class="references">تحقق 11 نوفمبر 2026: <a href="https://www.testrail.com/pricing/" target="_blank" rel="noopener">TestRail</a> · <a href="https://www.qase.io/pricing/" target="_blank" rel="noopener">Qase</a> · <a href="https://developers.cloudflare.com/workers-ai/platform/pricing/" target="_blank" rel="noopener">Cloudflare</a><br>مقارنة رسوم، لا تكافؤ وظائف أو إثبات انخفاض التكلفة الإجمالية.</p>', 'الاشتراك السنوي TestRail22×5×12=1320؛ Qase35×5×12=2100. العائد5ساعات سيناريو افتراضي لا قياس. لا رسوم اشتراك لا يعني صفر تكلفة ملكية. خطة Cloudflare المجانية10000Neurons يوميًا، وحد التطبيق20محاولة مشتركة يوميًا؛ لا يتساويان ولا fallback مدفوع. الحصة قد تنفد قبل عدد المحاولات. المصدر مفتوح للتعديل لكن الصيانة مسؤولية المستخدم. SaaS يدعم التخصيص ويوفر قدرات أوسع، ولا يصح القول إنه أقل مرونة مطلقًا.', 3), ('improvements', '08 · فرص التحسين', 'فرص التحسين', '<p class="lead">ثلاث إضافات للاستخدام الفعلي داخل المؤسسة، امتدادًا لتجارب خالد السابقة في الأنظمة الداخلية.</p><div class="improvement-visuals"><article data-reveal="1"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="20" r="11"/><path d="M10 57v-7a22 22 0 0 1 44 0v7M44 38l6 5 10-12"/></svg><span class="num">01</span><h3>حسابات وصلاحيات</h3><p>حساب مستقل لكل شخص، وأدوار للمختبِر والمطور والمراجع.</p></article><article data-reveal="2"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><rect x="5" y="5" width="22" height="22" rx="4"/><rect x="37" y="5" width="22" height="22" rx="4"/><rect x="5" y="37" width="22" height="22" rx="4"/><path d="M38 38h21v21H38ZM32 12h5M16 27v10m11 11h11M48 27v11"/></svg><span class="num">02</span><h3>موديول داخل ERP</h3><p>دمج مرن في النظام الحالي وربط الاختبارات بالمشاريع والمهام والموظفين.</p></article><article data-reveal="3"><svg class="semantic-icon " viewBox="0 0 64 64" aria-hidden="true"><path d="M17 49h30a12 12 0 0 0 3-24A19 19 0 0 0 14 25a12 12 0 0 0 3 24Z"/><path d="m24 36 8-8 8 8M32 28v29"/></svg><span class="num">03</span><h3>بوابة للمطورين</h3><p>رفع الإصدارات وملفات المتطلبات، واستقبالها لدى فريق الاختبار ومتابعة نتائجها.</p></article></div><p class="small">هذه إضافات مقترحة للأداة؛ تعتمد على خبرة سابقة وليست وظائف جاهزة فيها حاليًا.</p><p class="references">المصدر وخطوات التشغيل: <a href="https://github.com/KYA24/sarj-qa" target="_blank" rel="noopener">github.com/KYA24/sarj-qa</a></p>', 'ثلاث فرص فقط حسب الهيكل المعتمد. دخول Google للمالك موجود؛ المقترح توسيعه لهوية المؤسسة والصلاحيات متعددة المستخدمين، لا الادعاء بأنه غير موجود.', 3)]
